    private static final Map<String, Moneda> BY_CLAVE =
            VALUES.stream().collect(Collectors.toUnmodifiableMap(CatalogKey::clave, Function.identity()));

    private final Integer decimales;
    private final BigDecimal porcentajeVariacion;

    private Moneda(String clave, String descripcion, Vigencia vigencia, Integer decimales, BigDecimal porcentajeVariacion) {
        super(clave, descripcion, vigencia, true);
        this.decimales = decimales;
        this.porcentajeVariacion = porcentajeVariacion;
    }

    private Moneda(String clave) {
        super(clave, null, null, false);
        this.decimales = null;
        this.porcentajeVariacion = null;
    }

    /**
     * Returns the catalog entry for a key. Never fails for a non-null key: a key that is not in
     * the catalog yields an instance whose {@link #isKnown()} is {@code false}.
     *
     * @param clave the key as written in the XML
     * @return the entry
     */
    public static Moneda of(String clave) {
        Objects.requireNonNull(clave, "clave");
        Moneda known = BY_CLAVE.get(clave);
        return known != null ? known : new Moneda(clave);
    }

    /**
     * Returns every key of the catalog, in catalog order.
     *
     * @return the known keys
     */
    public static List<Moneda> values() {
        return VALUES;
    }

    /**
     * Returns the number of decimals the currency supports (column "Decimales").
     *
     * @return the value; empty for an unknown key or when the catalog leaves it blank
     */
    public OptionalInt decimales() {
        return decimales == null ? OptionalInt.empty() : OptionalInt.of(decimales);
    }

    /**
     * Returns the allowed exchange-rate variation as a fraction, for example {@code 5.00} for
     * 500 % (column "Porcentaje variación").
     *
     * @return the value; empty for an unknown key or when the catalog leaves it blank
     */
    public Optional<BigDecimal> porcentajeVariacion() {
        return Optional.ofNullable(porcentajeVariacion);
    }

    @Override
    public boolean equals(Object other) {
        return other instanceof Moneda that && clave().equals(that.clave());
    }

    @Override
    public int hashCode() {
        return clave().hashCode();
    }
